let ui={screen:'home',selected:'bennett',talents:[],talentPick:null,allTalents:false,exclusive:false,draftStep:0,tab:'season',sim:false,speed:450,interval:null,modal:null,storyEvent:null,offTab:'train',toast:null};
let career=null;
/* ===== 素材位资源映射：按素材位名称解析到 assets/ 下的图片；缺图时回退为占位框 ===== */
const ASSET_IMG={
 '游戏封面主视觉':'cover','封面主视觉':'cover','封面主视觉待加入':'draft-night',
 '封面纪录片主视觉':'cover-doc','选秀之夜舞台背景':'draft-night',
 '全明星周末主视觉':'allstar','常规赛结束阶段主视觉':'regular-end',
 '附加赛生死战主视觉':'playin','休赛期训练馆主视觉':'offseason-gym',
 '联盟页面顶部主视觉':'league','联盟排名页面主视觉':'league',
 '交易新闻主视觉':'trade','生涯荣誉陈列馆背景':'hall-of-fame',
 '该主线章节剧情插图':'story-illust','本章剧情插图':'story-illust',
 '本章剧情CG':'story-illust','剧情插图':'story-illust'
};
/* 素材位里的中文球员名 → 文件名用的 id。顺序固定：本内特 / 奥登 / 夸梅 / 富尔茨 / 西蒙斯 */
const ASSET_NAME_ID={'安东尼·本内特':'bennett','格雷格·奥登':'oden','夸梅·布朗':'kwame','马克尔·富尔茨':'fultz','本·西蒙斯':'simmons'};
/* 素材位后缀 → 文件名前缀。人物立绘与球员详情立绘共用同一张，一人一张即可 */
const ASSET_KIND_FILE={'人物立绘':'portrait','人物形象':'portrait','球员详情立绘':'portrait','生涯主界面立绘':'hero','赛季主视觉':'season','当前赛季主视觉':'season','当前球队时期主视觉':'season','专属主线章节视觉':'story','退役生涯海报':'retire'};
/* 随包发布的真实图片资源清单（由构建时扫描 assets/ 生成）：只引用确实存在的文件 */
const ASSET_AVAILABLE=["assets/allstar.jpg","assets/cover-doc.jpg","assets/cover.jpg","assets/draft-night.jpg","assets/hall-of-fame.jpg","assets/league.jpg","assets/offseason-gym.jpg","assets/playin.jpg","assets/portrait-bennett.jpg","assets/portrait-fultz.jpg","assets/portrait-kwame.jpg","assets/portrait-oden.jpg","assets/portrait-simmons.jpg","assets/portrait-griffin.jpg","assets/portrait-risacher.jpg","assets/portrait-wall.jpg","assets/portrait-wiggins.jpg","assets/portrait-zion.jpg","assets/portrait-yao.jpg","assets/regular-end.jpg","assets/story-illust.jpg","assets/trade.jpg","assets/portrait-rose.jpg"];
function assetFile(title){
 const t=String(title).replace(/^【素材位：/,'').replace(/】$/,'').trim();
 if(ASSET_IMG[t])return ASSET_AVAILABLE.indexOf('assets/'+ASSET_IMG[t]+'.jpg')>=0?'assets/'+ASSET_IMG[t]+'.jpg':null;
 if(/奖杯图标$/.test(t))return ASSET_AVAILABLE.indexOf('assets/trophy.jpg')>=0?'assets/trophy.jpg':null;
 const m=t.match(/^(.+?)(人物立绘|人物形象|球员详情立绘|生涯主界面立绘|赛季主视觉|当前赛季主视觉|当前球队时期主视觉|专属主线章节视觉|退役生涯海报)$/);
 if(!m)return null;
 const id=ASSET_NAME_ID[m[1]],prefix=ASSET_KIND_FILE[m[2]];
 if(!id||!prefix)return null;
 return ASSET_AVAILABLE.indexOf('assets/'+prefix+'-'+id+'.jpg')>=0?'assets/'+prefix+'-'+id+'.jpg':null;
}
/* 2026-10-27：三张场景停用，不在游戏里显示任何占位框 */
const HIDDEN_ASSET_TITLE=/常规赛结束阶段主视觉|联盟页面顶部主视觉|联盟排名页面主视觉|本章剧情CG|本章剧情插图|该主线章节剧情插图|剧情插图/;
function asset(title,desc,cls=''){
 if(HIDDEN_ASSET_TITLE.test(String(title||'')))return '';
 const ph=`<div class="asset-fallback"><b>${esc(title)}</b>${esc(desc)}</div>`;
 const file=assetFile(title);
 if(file)return `<div class="asset-slot ${cls} has-img"><img src="${file}" alt="${esc(String(title))}" loading="lazy" onerror="this.parentNode.classList.remove('has-img');this.remove()">${ph}</div>`;
 return `<div class="asset-slot ${cls}">${ph}</div>`;
}
function currentP(){return playerBy(career?.playerId||ui.selected)}
function hasTalent(id){return career?.talents?.includes(id)||false}
function save(){try{if(career)localStorage.setItem(SAVE,JSON.stringify(career))}catch(e){/* file:// 或受限预览环境下允许无存档继续运行 */}}
function load(){try{let x=JSON.parse(localStorage.getItem(SAVE));if(x&&x.playerId&&playerBy(x.playerId))return x}catch(e){}return null}
function notify(t){ui.toast=t;render();setTimeout(()=>{if(ui.toast===t){ui.toast=null;render()}},1800)}
function roleByOvr(o){if(o>=94)return'联盟门面';if(o>=90)return'超级巨星';if(o>=86)return'全明星核心';if(o>=82)return'球队核心';if(o>=78)return'稳定首发';if(o>=74)return'轮换球员';return'边缘球员'}
function minutesByRole(r){return {'联盟门面':36,'超级巨星':35,'全明星核心':34,'球队核心':32,'稳定首发':29,'轮换球员':22,'边缘球员':14}[r]||20}
function calcOvr(a){return Math.round(a.finishing*.16+a.shooting*.13+a.playmaking*.14+a.defense*.16+a.rebounding*.12+a.athleticism*.11+a.durability*.09+a.mentality*.09)}
function syncOvr(){career.ovr=clamp(calcOvr(career.attrs)+career.ovrMod,50,99);career.role=roleByOvr(career.ovr);career.minutes=Math.min(career.minutesLimit||99,minutesByRole(career.role)+(hasTalent('core')?2:0))}
function applyFx(f={}){if(f.a)for(const[k,v]of Object.entries(f.a))career.attrs[k]=clamp(career.attrs[k]+v,30,99);if(f.h)career.health=clamp(career.health+f.h);if(f.c)career.confidence=clamp(career.confidence+f.c);if(f.tr)career.trust=clamp(career.trust+f.tr);if(f.s)career.special=clamp(career.special+f.s);if(f.o)career.ovrMod+=f.o;if(f.min)career.minutesLimit=f.min;if(f.trade)career.tradeRequest=f.trade;if(f.teamTrade)career.teamTradePressure=(career.teamTradePressure||0)+f.teamTrade;syncOvr();save()}
function drawTalents(){ui.talents=[];let pool=[...talents];while(ui.talents.length<4){let i=rnd(0,pool.length-1);ui.talents.push(pool.splice(i,1)[0])}if(!ui.talents.some(x=>x.r==='传奇'))ui.talents[0]=talents.find(x=>x.id==='learn');ui.talentPick=null;ui.allTalents=false;ui.exclusive=false}
function startSelect(){stopSim();ui.screen='select';ui.selected='bennett';render()}
function openTalents(){drawTalents();ui.screen='talents';render()}
async function takeAll(){await rewardAd.request('take_all_talents');ui.allTalents=true;render();notify('四个随机天赋已全部带走')}
async function unlockExclusive(){await rewardAd.request('exclusive_talent');ui.exclusive=true;render();notify('专属天赋已解锁')}
function enterDraft(){if(!ui.allTalents&&ui.talentPick==null)return notify('先选择一个免费天赋');ui.screen='draft';ui.draftStep=0;render()}
function draftLines(p){if(p&&p.id==='custom'&&window.__DRAFTX__){return window.__DRAFTX__(p)}const lines={bennett:['2013年，布鲁克林。','克利夫兰拥有第一顺位。','没有人猜到接下来会被念出的名字。','Anthony Bennett.','状元。','错愕和质疑，从这一秒开始。','但这一次，命运还没有写完。'],oden:['2007年。','开拓者手握状元签。','一个被视作未来统治级中锋的年轻人站在台下。','Greg Oden.','状元。','没有人知道，真正决定他生涯的也许不是篮球。','这一次，保护好他的身体。'],kwame:['2001年。','他还没有打过一场大学篮球。','十九岁，直接站到NBA最亮的灯下。','Kwame Brown.','状元。','天赋、期待、压力在同一夜落下来。','这一次，别让期待毁掉成长。'],fultz:['2017年。','费城为了第一顺位向上交易。','目标只有一个。','Markelle Fultz.','状元。','人们相信后场答案已经出现。','这一次，把熟悉的投篮留在他身上。'],simmons:['2016年。','尺寸、视野、运动能力。','一个几乎无法用传统位置定义的天才。','Ben Simmons.','状元。','天赋看起来足以通向超级巨星。','但天赋从来不等于结局。']};return lines[p.id]}
function nextDraft(){let p=currentP(),lines=draftLines(p);if(ui.draftStep<lines.length-1){ui.draftStep++;render()}else createCareer()}
function blankStats(){return{gp:0,pts:0,reb:0,ast:0,stl:0,blk:0,fg:0,three:0,totalPts:0,totalReb:0,totalAst:0}}
function seasonMission(){let p=currentP(),s=career.seasonStats;if(p.id==='bennett')return{t:'摆脱“只剩状元标签”',d:'把教练信任拉到60以上，并站稳轮换',v:Math.round((career.trust+Math.min(60,career.special))/1.6),txt:`信任 ${career.trust} · 逆风 ${career.special}`};if(p.id==='oden')return{t:'完整地留在球场上',d:'控制身体风险，健康完成尽可能多的比赛',v:Math.round(((100-career.special)+career.health)/2),txt:`风险 ${career.special} · 出战 ${s.gp}`};if(p.id==='kwame')return{t:'先成长，再证明状元',d:'让成长耐心保持在高位，避免被压力拔苗助长',v:Math.round((career.special+career.confidence)/2),txt:`耐心 ${career.special} · 自信 ${career.confidence}`};if(p.id==='fultz')return{t:'找回可以相信的投篮',d:'把投篮稳定与投射一起拉回NBA可靠水平',v:Math.round((career.special+career.attrs.shooting)/2),txt:`稳定 ${career.special} · 投射 ${career.attrs.shooting}`};return{t:'不再逃避半场进攻',d:'提高主动进攻意愿，并建立可用投射',v:Math.round((career.special+career.attrs.shooting)/2),txt:`欲望 ${career.special} · 投射 ${career.attrs.shooting}`}}
function mainlineEnding(){let p=currentP();if(p.id==='bennett'){if(career.ovr>=88&&career.special>=70)return['彻底翻案','“最差状元”已经无法解释这段生涯。'];if(career.ovr>=80)return['站稳NBA','你先救活了职业生涯，再谈状元身份。'];return['仍在逆风里','标签还在，但世界线已经开始松动。']}if(p.id==='oden'){if(career.special<=35&&career.health>=72&&career.careerTotals.seasons>=4)return['健康的统治者','你做到了最难的事：让天赋有时间留在球场。'];if(career.special<=55)return['和身体达成停战','风险仍在，但它不再完全控制生涯。'];return['仍在与身体赛跑','每一次高负荷都还在向未来借时间。']}if(p.id==='kwame'){if(career.ovr>=86&&career.special>=70)return['迟到的兑现','你没有催熟他，最终等到了真正的成熟。'];if(career.ovr>=79)return['找到自己的位置','状元期待不再是唯一评价标准。'];return['成长仍未完成','压力和成熟度之间的拉扯还没有结束。']}if(p.id==='fultz'){if(career.special>=75&&career.attrs.shooting>=72)return['投篮真的回来了','你不再是在修动作，而是在正常打篮球。'];if(career.special>=58)return['重新敢投','投篮仍不是武器，但已经不再主宰整个生涯。'];return['仍在寻找熟悉感','那个最普通的动作仍然需要被重新相信。']}if(career.special>=68&&career.attrs.shooting>=58)return['主动进攻版本','防守和组织之外，你终于逼出了第三种威胁。'];if(career.special>=55)return['重新定义超级巨星','没有变成射手，但不再主动退出关键回合。'];return['天赋仍有缺口','最强的能力和最大的弱点仍同时存在。']}
function managementTradeRisk(){let risk=8;if(career.tradeRequest)risk+=55;if(career.trust<45)risk+=18;if(career.contract.years<=1)risk+=9;if(career.ovr<78)risk+=8;if(career.ovr>=90)risk-=6;risk+=(career.teamTradePressure||0)*12;let tp=teamBy(career.team).power;if(tp<80&&career.ovr>=86)risk+=5;if(tp>=89&&career.ovr<80)risk+=9;return clamp(Math.round(risk),3,88)}
function managementStance(){let r=managementTradeRisk();if(career.tradeRequest)return['你已主动要求改变环境',`管理层正在评估市场，当前交易风险约 ${r}%。`];if(r>=55)return['管理层正在认真听报价',`球队规划、合同与当前角色让你的未来变得不稳定。风险约 ${r}%。`];if(r>=30)return['球队愿意听，但不急着卖',`你不是非卖品，但管理层不会为了交易而交易。风险约 ${r}%。`];return['管理层目前倾向留队',`除非出现明显升级机会，否则球队更愿意继续合作。风险约 ${r}%。`]}
function stableHash(str){let h=2166136261;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return Math.abs(h>>>0)}
function projectedWins(t){if(t.abbr===career.team&&career.games>0)return Math.round(career.wins/career.games*82);let jitter=stableHash(t.abbr+'-'+career.seasonYear)%13-6;return clamp(Math.round(24+(t.power-74)*1.65+jitter),18,68)}
