function addPoint(k){if(career.devPoints<=0)return;career.attrs[k]=clamp(career.attrs[k]+1,30,99);if(hasTalent('shot')&&k==='shooting')career.attrs[k]=clamp(career.attrs[k]+1,30,103);if(hasTalent('gym')&&['athleticism','durability'].includes(k))career.attrs.durability=clamp(career.attrs.durability+1,30,99);career.devPoints--;syncOvr();save();render()}
function acceptOffer(i){let o=career.offers[i],t=teamBy(o.team);career.team=o.team;career.contract={years:o.years,salary:o.salary};career.offers=[];career.trust=65;career.feed.unshift(`合同签署：${o.years}年 ${o.salary}M/年，与${t.name}达成协议。`);save();render()}
function requestRenewal(){if(career.contract.years===0)return notify('当前已经进入自由市场，请直接选择报价');if(career.offers.some(o=>o.type==='EXT'))return notify('球队已经给出了续约报价');let score=career.ovr+career.trust*.12+career.health*.04-career.age*.12;let need=82+(career.contract.years>2?7:0);if(score>=need){let base=Math.max(10,Math.round((career.ovr-70)*2.6));career.offers=[{team:career.team,years:rnd(3,5),salary:Math.round(base*(.95+Math.random()*.18)),type:'EXT'}];career.feed.unshift('你主动提出续约后，球队给出了正式报价。')}else{career.feed.unshift('你主动提出续约，但管理层决定暂时观望。');career.trust=clamp(career.trust-1)}save();render()}
function requestTrade(type){career.tradeRequest=type;career.feed.unshift(`你已向管理层提出交易申请：${type}。`);save();render()}
function ageCurve(){career.age++;let p=currentP(),growth=0;if(career.age<=23)growth=hasTalent('learn')?1.35:1;if(p.id==='kwame'&&hasTalent('kwame_x')&&career.age<=23)growth+=.55;if(growth>0){for(const k of Object.keys(career.attrs))if(Math.random()<.32*growth)career.attrs[k]=clamp(career.attrs[k]+1,30,99)}
 if(career.age>=30){let long=hasTalent('long'),age=career.age,physical=['athleticism','durability','finishing','defense'];let base=age>=41?1:age>=38?.92:.52;if(long)base*=.8;for(const k of physical){if(Math.random()<base){let drop=1;if(age>=41&&!long&&Math.random()<.45)drop++;career.attrs[k]=clamp(career.attrs[k]-drop,30,99)}}let skillChance=age>=41?.72:age>=38?.46:.18;if(long)skillChance*=.82;for(const k of ['shooting','playmaking','rebounding'])if(Math.random()<skillChance)career.attrs[k]=clamp(career.attrs[k]-1,30,99);if(age>=38){career.ovrMod-=long&&Math.random()<.45?0:1;if(age>=40&&!long)career.ovrMod--;else if(age>=42&&long&&Math.random()<.35)career.ovrMod--}else if(age>=34&&Math.random()<.48)career.ovrMod--}
 if(hasTalent('late')&&career.age>=30&&!career.flags.secondSpring){career.flags.secondSpring=true;career.attrs.mentality=clamp(career.attrs.mentality+2,30,99);career.attrs.shooting=clamp(career.attrs.shooting+1,30,99);career.ovrMod++}syncOvr()}
function resolveTransactions(){if(career.contract.years===0&&career.offers.length)return false;let chance=(career.tradeRequest?72:0)+(career.trust<45?18:0)+(career.teamTradePressure||0)*14+(career.contract.years===1?7:0);if(!career.tradeRequest&&chance===0)chance=8;if(Math.random()*100<chance){let choices=teams.filter(t=>t.abbr!==career.team);if(career.tradeRequest==='争冠球队')choices=choices.filter(t=>t.power>=87);if(career.tradeRequest==='更多机会')choices=choices.filter(t=>t.power<=84);let d=pick(choices.length?choices:teams.filter(t=>t.abbr!==career.team));let old=teamBy(career.team).name;career.team=d.abbr;career.trust=hasTalent('adapt')?65:55;career.feed.unshift(`休赛期交易：${old}将你送往${d.name}。${career.tradeRequest?'你的交易申请被执行。':'这是管理层主动做出的决定。'}`);career.tradeRequest=null;career.teamTradePressure=0;ui.modal={kind:'offtrade',dest:d,old};return true}career.tradeRequest=null;career.teamTradePressure=0;return false}
function nextSeason(){if(career.devPoints>0&&career.ovr<99)return notify(`还有${career.devPoints}点没有使用`);if(career.contract.years===0&&career.offers.length)return notify('合同已到期，必须先选择一份合同');ageCurve();const retireFloor=(career.playerId==='custom'&&career.age<27)?64:72;
 /* 自建球员由玩家自己决定何时退役，不因 OVR 跌破阈值被系统强制结束。 */
 if(career.playerId!=='custom'&&career.ovr<retireFloor){retire(`评分跌破${retireFloor}，联盟没有球队愿意继续提供稳定位置`);return}resolveTransactions();career.seasonNo++;career.seasonYear++;career.stage='regular';career.games=0;career.wins=0;career.losses=0;career.seasonStats=blankStats();career.gameLog=[];career.allStar=null;career.allStarLine=null;career.allstarChecked=false;career.deadlineChecked=false;career.playoff=null;career.currentSeed=null;career.seasonStartOvr=career.ovr;career.health=clamp(career.health+10);career.confidence=clamp(career.confidence+2);career.feed.unshift(`${seasonLabel()}开始，你以${career.role}身份进入新赛季。`);save();render()}
function retire(reason='玩家主动宣布退役'){
 /* 自建球员只由玩家自己决定退役：系统性的状态下滑、年龄、评分跌破阈值都不能替他结束生涯。 */
 if(career&&career.playerId==='custom'&&!/主动|选择|落选后未能留在 NBA|结束这段生涯/.test(String(reason)))return;
 stopSim();career.retired=true;career.retireReason=reason;career.stage='retired';save();ui.screen='retired';render()}
function storyChoice(i){let ev=ui.storyEvent,ch=ev.c[i];applyFx(ch[2]);career.feed.unshift(`专属主线「${ev.t}」：你选择了“${ch[0]}”。`);career.storyIndex++;ui.storyEvent=null;save();render()}
function honorCount(){return Object.values(career.honors).reduce((a,b)=>a+b,0)}
function destinyScore(){let base=(career.ovr-70)*3+career.careerTotals.seasons*2+career.honors['全明星']*3+career.honors['最佳阵容']*4+career.honors['MVP']*12+career.honors['总冠军']*8;return clamp(Math.round(base),0,100)}
function renderHome(){let s=load();return `<section class="cover"><div class="cover-kicker"><b>CAREER REWRITE</b><span>单文件版 · 双击即玩</span></div><div class="cover-title"><small>五个状元 · 五条独立命运主线</small><h1><span>拯救</span><em>水货状元</em></h1><p>不是“点一年看结果”。从选秀夜开始，亲手活过82场常规赛、全明星、伤病、交易、季后赛和一次又一次职业选择。</p></div><div class="cover-art">${asset('【素材位：游戏封面主视觉】','用途：五位状元围绕选秀舞台/球馆灯光构图；画面明亮、高级、热血，不要文字，不要用前端人物占位替代。','tall')}<div class="cover-art-note"><small>FIVE EXCLUSIVE STORIES</small><strong>本内特 · 奥登 · 夸梅 · 富尔茨 · 西蒙斯</strong></div></div><div class="cover-scenarios"><span>82场可随时暂停</span><span>红绿豆胜负轨迹</span><span>重大伤病</span><span>全明星揭晓</span><span>交易与续约</span><span>逐轮季后赛</span></div><div class="cover-actions"><button class="btn primary" onclick="startSelect()">开始改写生涯 →</button>${s?`<button class="btn secondary" onclick="continueSave()">继续 ${esc((playerBy(s.playerId)||{}).zh||'未知球员')} · ${s.seasonYear}-${String((s.seasonYear+1)%100).padStart(2,'0')}</button>`:''}<div class="tiny" style="text-align:center">所有需要正式美术的地方均保留为空素材位，并标明用途。</div></div></section>`}
function renderSelect(){let p=playerBy(ui.selected);return `<section class="pre"><div class="pre-top"><button class="circle-btn" onclick="ui.screen='home';render()">←</button><strong>选择要拯救的状元</strong><span style="width:36px"></span></div><div class="pre-intro"><small>CHOOSE A CAREER</small><h2>五种失败，五种救法</h2><p>不是五张换皮卡。每个人拥有独立数值机制、专属主线、关键矛盾和不同的生涯风险。</p></div><div class="scenario-deck">${P.map(x=>`<button class="scenario-card ${ui.selected===x.id?'selected':''}" onclick="ui.selected='${x.id}';render()">${asset(`【素材位：${x.zh}人物立绘】`,'用途：剧本选择卡头像/半身像，不要名字文字')}<div><div class="meta">${x.year} · ${teamBy(x.team).name} · ${x.pos}</div><h3>${x.zh}</h3><p><b>${x.title}</b><br>${x.tagline}</p><div class="scenario-tags">${x.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="scenario-ovr"><b>${x.ovr}</b><small>初始 OVR</small></div></div></button>`).join('')}</div><div class="sticky-cta"><button class="btn primary" onclick="openTalents()">选择 ${p.zh} · 进入天赋抽取 →</button></div></section>`}
function renderTalents(){let p=playerBy(ui.selected);return `<section class="pre"><div class="pre-top"><button class="circle-btn" onclick="ui.screen='select';render()">←</button><strong>${p.zh} · 重写命运</strong><span style="width:36px"></span></div><div class="pre-intro"><small>DESTINY TALENTS</small><h2>先带走一份未来</h2><p>免费四选一。广告接口已预留，本地测试直接放行：可以四个全拿，也可以额外解锁该状元唯一专属天赋。</p></div><div class="talent-wrap"><div class="talent-grid">${ui.talents.map((t,i)=>`<button class="talent-card ${ui.talentPick===i?'selected':''}" onclick="ui.talentPick=${i};render()"><div class="rarity">${t.r}</div><h3>${t.n}</h3><p>${t.d}</p><div class="ghost">0${i+1}</div></button>`).join('')}</div><div class="reward-card"><div class="reward-icon">×4</div><div><small>奖励广告 · 本地直接成功</small><strong>我全都要：四个随机天赋全部带走</strong></div><button onclick="takeAll()">${ui.allTalents?'已解锁':'解锁'}</button></div><div class="reward-card exclusive"><div class="reward-icon">★</div><div><small>${p.zh}唯一专属</small><strong>${p.exclusive.n}</strong><div class="tiny">${p.exclusive.d}</div></div><button onclick="unlockExclusive()">${ui.exclusive?'已解锁':'解锁'}</button></div></div><div class="sticky-cta"><button class="btn primary" onclick="enterDraft()">进入选秀之夜 →</button></div></section>`}
function renderDraft(){let p=currentP(),lines=draftLines(p);return `<section class="draft"><div class="draft-inner">${asset('【素材位：选秀之夜舞台背景】','用途：选秀舞台/灯光/观众虚化背景；不要具体球员和文字')}<div class="draft-text">${esc(lines[ui.draftStep])}</div><small>点击继续 · 黑底白字剧情会逐段渐显</small><div class="draft-dots">${lines.map((_,i)=>`<i class="${i<=ui.draftStep?'on':''}"></i>`).join('')}</div><button class="btn" style="width:100%;margin-top:24px;background:#fff;color:#111" onclick="nextDraft()">${ui.draftStep===lines.length-1?'开始职业生涯':'继续'}</button></div></section>`}
function renderHud(){let p=currentP();return `<header class="career-hud"><div><small>${seasonLabel()} · ${career.age}岁 · ${seasonPhase()}</small><h2>${p.zh}<span> · ${teamBy(career.team).name}</span></h2></div><div class="hud-right">${asset('【球队Logo素材位】',career.team,'logo')}<div class="ovr-orb"><span>OVR</span><b>${career.ovr}</b></div></div></header>`}
function seasonHero(){let p=currentP(),prog=career.stage==='regular'?career.games/82*100:career.stage==='allstar'?50:career.stage==='postgate'||career.stage==='playoffs'||career.stage==='playin'||career.stage==='offseason'?100:0,m=seasonMission();return `<section class="season-arena"><div class="arena-head"><div><small>${seasonLabel()} · YEAR ${career.seasonNo}</small><h3>${seasonPhase()}</h3></div><span class="stage-chip">${career.role}</span></div><div class="arena-body">${asset(`【素材位：${p.zh}生涯主界面立绘】`,'用途：球员主界面半身/全身立绘；随球队变化不改文字')}<div class="identity"><div class="role">${teamBy(career.team).name} · ${p.pos}</div><h1>${p.zh}</h1><p>${career.feed[0]||p.tagline}</p><div class="three-meters"><div><b>${career.health}</b><span>健康</span></div><div><b>${career.confidence}</b><span>自信</span></div><div><b>${career.special}</b><span>${p.specialName}</span></div></div></div></div><div class="mission-strip"><div class="mission-icon">◆</div><div><small>本季主线目标</small><b>${m.t}</b><p>${m.d}</p></div><div class="mission-progress">${m.txt}</div></div><div class="season-progress"><div class="progress-top"><span>赛季旅程</span><b>${career.games}/82 · ${teamRecord()}</b></div><div class="track"><i style="width:${clamp(prog)}%"></i></div><div class="milestones"><span>揭幕</span><span>全明星</span><span>交易截止</span><span>季后赛</span></div></div></section>`}
function renderBeans(){let g=career.gameLog.slice(0,20).reverse();return `<div class="beans">${g.length?g.map(x=>`<span class="bean ${x.win?'win':'loss'} ${x.played===false?'inj':''}" title="${x.win?'胜':'负'}"></span>`).join(''):'<span class="tiny">赛季还没有比赛记录</span>'}</div>`}
function scoreTicker(){return `<div class="score-ticker">${career.gameLog.slice(0,6).map(g=>`<article class="game-card ${g.win?'win':'loss'}"><header><span>${g.n==='附加赛'?'PLAY-IN':`GAME ${g.n}`}</span><b>${g.win?'WIN':'LOSS'}</b></header><div class="score">${career.team} ${g.sf} : ${g.sa} ${g.opp}</div><p>${g.played===false?'伤病缺阵':`${fmt(g.line?.pts)}分 · ${fmt(g.line?.reb)}板 · ${fmt(g.line?.ast)}助`}</p></article>`).join('')}</div>`}
function regularView(){let s=career.seasonStats,p=currentP();return `${seasonHero()}<section class="cockpit"><div class="cockpit-top"><div><small>REGULAR SEASON SIMULATOR</small><strong>常规赛连续模拟</strong></div><span class="tiny">随时暂停</span></div><div class="sim-row"><button class="sim-main ${ui.sim?'running':''}" onclick="toggleSim()">${ui.sim?'Ⅱ 暂停':'▶ 开始模拟常规赛'}</button><button class="speed-btn" onclick="changeSpeed()">${ui.speed===450?'1×':ui.speed===220?'2×':'4×'}</button></div><div class="beans-head"><b>最近20场 · 红绿豆</b><span>绿=胜 · 红=负 · 灰点=伤停</span></div>${renderBeans()}</section>${scoreTicker()}<div class="dashboard"><section class="dash-card"><h3>本赛季个人数据</h3><div class="stat-line"><div><b>${fmt(s.pts)}</b><span>PTS</span></div><div><b>${fmt(s.reb)}</b><span>REB</span></div><div><b>${fmt(s.ast)}</b><span>AST</span></div></div><div class="stat-line" style="margin-top:5px"><div><b>${fmt(s.fg)}%</b><span>FG</span></div><div><b>${fmt(s.three)}%</b><span>3P</span></div><div><b>${s.gp}</b><span>GP</span></div></div></section><section class="dash-card"><h3>当前状态</h3><div class="status-stack"><div class="status-bar"><span><i>健康</i><b>${career.health}</b></span><i><b style="width:${career.health}%"></b></i></div><div class="status-bar"><span><i>信任</i><b>${career.trust}</b></span><i><b style="width:${career.trust}%"></b></i></div><div class="status-bar"><span><i>${p.specialName}</i><b>${career.special}</b></span><i><b style="width:${career.special}%"></b></i></div></div></section></div>${career.injury?`<section class="news-stage" style="border-color:#efc4c6;background:#fff2f2"><header><h3>医疗组伤病报告</h3><small>${career.injury.severity.toUpperCase()}</small></header><div class="headline"><div class="stamp">INJ</div><p><b>${career.injury.name}</b><br>预计还将缺席 ${career.injury.gamesLeft} 场。常规赛会继续，但伤停比赛不会计入个人数据。</p></div></section>`:''}<section class="news-stage"><header><h3>生涯正在发生</h3><small>LIVE CAREER</small></header><div class="headline"><div class="stamp">NOW</div><p><b>${career.feed[0]||'新的赛季开始了。'}</b><br>${career.feed[1]||'下一次重大节点会自动暂停模拟。'}</p></div></section>`}
function allStarView(){let yes=career.allStar,l=career.allStarLine;return `${seasonHero()}<section class="stage-card" style="margin-top:10px">${asset('【素材位：全明星周末主视觉】','用途：全明星球馆、灯光、星形舞台；不出现具体球员文字','banner')}<div class="stage-copy"><div class="big-icon">★</div><span class="result-label">${yes?'正式入选全明星':'本季未入选'}</span><h2>${yes?'你的名字出现在全明星名单里':'名单公布，没有你的名字'}</h2><p>${yes?'这是这条世界线里真正的身份跃迁。入选会进入最终履历，也会提高续约、交易价值和球队地位。':'落选并不会结束赛季。后半程、季后赛和专属主线仍然可以改变所有人的评价。'}</p>${yes&&l?`<div class="allstar-line"><div><b>${fmt(l.pts)}</b><span>PTS</span></div><div><b>${fmt(l.reb)}</b><span>REB</span></div><div><b>${fmt(l.ast)}</b><span>AST</span></div></div>`:''}${yes&&!l?`<button class="btn gold" style="width:100%;margin-top:12px" onclick="playAllStar()">出战全明星正赛 ★</button>`:`<button class="btn primary" style="width:100%;margin-top:12px" onclick="resumeAllStar()">继续后半程常规赛 →</button>`}</div></section>`}
function postGateView(){let s=career.seasonStats,seed=career.currentSeed;return `${seasonHero()}<section class="stage-card" style="margin-top:10px">${asset('【素材位：常规赛结束阶段主视觉】','用途：球馆记分牌/赛季收官氛围图，不要文字','banner')}<div class="stage-copy"><span class="result-label">REGULAR SEASON COMPLETE</span><h2>${teamRecord()} · 东/西部第 ${seed}</h2><p>你完成了${s.gp}场出战，场均 ${fmt(s.pts)} 分 ${fmt(s.reb)} 篮板 ${fmt(s.ast)} 助攻。${seed<=6?'球队直接进入季后赛。':seed<=10?'球队进入附加赛，下一场就是生死战。':'球队无缘季后赛，本赛季将进入休赛期。'}</p><button class="btn primary" onclick="enterPostseason()">${seed<=6?'进入季后赛 →':seed<=10?'进入附加赛 →':'进入休赛期 →'}</button></div></section>`}
function playInView(){return `${seasonHero()}<section class="stage-card" style="margin-top:10px">${asset('【素材位：附加赛生死战主视觉】','用途：一场定生死的球馆海报氛围，不要人物文字','banner')}<div class="stage-copy"><span class="result-label">PLAY-IN</span><h2>赢下这一场，进入季后赛</h2><p>82场常规赛结束后，一切被压缩成一场。伤病、健康、自信和你整个赛季积累的能力都会影响结果。</p><button class="btn primary" onclick="playInGame()">模拟附加赛 →</button></div></section>`}
function playoffView(){let po=career.playoff,r=po.rounds[po.round],names=['首轮','分区半决赛','分区决赛','总决赛'];return `<div class="po-road">${names.map((x,i)=>`<div class="${i<po.round?'done':i===po.round?'on':''}">${x}</div>`).join('')}</div><section class="po-stage"><div class="po-stage-top"><small>${r.name.toUpperCase()} · BEST OF SEVEN</small><h2>${teamBy(career.team).name}<br>vs ${r.oppName}</h2><div class="series-big">${r.w}-${r.l}</div></div><div class="matchup"><div class="team-box">${asset('【素材位：我方球队Logo】',career.team,'logo')}<b>${career.team}</b></div><div class="vs">VS</div><div class="team-box">${asset('【素材位：对手球队Logo】',r.opp,'logo')}<b>${r.opp}</b></div></div><div class="po-games">${r.games.length?r.games.map((g,i)=>`<div class="po-game ${g.win?'win':'loss'} ${g.played===false?'dnp':''} ${g.roseBlast?'blast':''}"><span class="wl">${g.played===false?'DNP':g.win?'W':'L'}</span><div><strong>G${i+1} · ${career.team} ${g.sf}:${g.sa} ${r.opp}</strong><small>${g.played===false?'伤病缺阵，球队独自完成这一场':`你的表现：${fmt(g.line?.pts)}分 ${fmt(g.line?.reb)}板 ${fmt(g.line?.ast)}助`}</small></div><small>${g.win?'拿下一场':'丢掉一场'}</small></div>`).join(''):`<div class="tiny" style="padding:8px">系列赛还没有开始。每场胜负都会用红/绿底清晰演出。</div>`}</div><div class="po-actions"><button class="next" onclick="playoffGame()">模拟下一场</button><button class="auto" onclick="simSeries()">一键模拟本轮</button></div></section><section class="news-stage"><header><h3>季后赛压力</h3><small>PRESSURE MODE</small></header><div class="headline"><div class="stamp">PO</div><p><b>健康 ${career.health} · 自信 ${career.confidence}</b><br>${career.injury?`你正因${career.injury.name}缺阵，还需约${career.injury.gamesLeft}场。球队不会因为你受伤而停止系列赛。`:'季后赛也可能受伤；越深的轮次，身体和大心脏天赋越重要。'}</p></div></section>`}
function offTrain(){return `<div class="add-grid">${Object.entries(ATTR).map(([k,v])=>`<button class="add-btn" onclick="addPoint('${k}')" ${career.devPoints<=0?'disabled':''}><div><span>${v}</span><b>${career.attrs[k]}</b></div><i>+1</i></button>`).join('')}</div>`}
function offContract(){let c=career.contract;return `<section class="agent-card"><h3>合同与续约</h3><p>你可以主动续约，也可以把未来押在自由市场。合同到期后必须先签约才能进入下一季。</p><div class="contract-grid"><div><span>剩余年限</span><b>${c.years}年</b></div><div><span>年薪</span><b>${c.salary}M</b></div><div><span>球队角色</span><b>${career.role}</b></div></div>${career.offers.length?career.offers.map((o,i)=>`<div class="offer"><div><strong>${teamBy(o.team).name}</strong><span>${o.type==='EXT'?'提前续约':'自由市场报价'} · ${o.years}年 · ${o.salary}M/年</span>${(typeof window.v101OfferInfo==='function'?window.v101OfferInfo(o.team):'')}</div><button onclick="acceptOffer(${i})">接受</button></div>`).join(''):`<div class="tiny">当前没有正式报价。评分、健康、球队地位和合同剩余年限会影响球队是否开价。</div>`}<button class="btn secondary" style="width:100%;margin-top:9px" onclick="requestRenewal()">主动申请续约</button></section>`}
function offTrade(){let m=managementStance(),risk=managementTradeRisk();return `<section class="agent-card"><h3>申请交易 / 管理层动向</h3><p>你能表达意愿，但你没有交易否决权。球队也可能因为重建、合同、角色适配或资产价值主动把你送走。</p><div class="contract-grid"><div><span>教练信任</span><b>${career.trust}</b></div><div><span>当前意愿</span><b>${career.tradeRequest||'愿意留队'}</b></div><div><span>合同</span><b>${career.contract.years}年</b></div></div><div class="gm-meter"><header><b>${m[0]}</b><span>${risk}%</span></header><div class="risktrack"><i style="width:${risk}%"></i></div><p>${m[1]}</p></div><div class="choice-list"><button class="choice" onclick="requestTrade('争冠球队')"><b>申请交易 · 去争冠球队</b><span>优先寻找高战力球队，但你的球权和角色可能下降。</span></button><button class="choice" onclick="requestTrade('更多机会')"><b>申请交易 · 要更多机会</b><span>优先去战力较弱、但更可能把你当核心培养的球队。</span></button><button class="choice" onclick="requestTrade('新环境')"><b>申请交易 · 只想换个环境</b><span>不限定目的地，管理层最容易找到成交方案。</span></button><button class="choice" onclick="career.tradeRequest=null;career.feed.unshift('你向管理层表态：愿意继续留队。');save();render()"><b>明确表态留队</b><span>降低主动推动交易的可能，但球队仍保留交易你的权力。</span></button></div></section>`}
function offseasonView(){return `<section class="off-hero">${asset('【素材位：休赛期训练馆主视觉】','用途：训练馆、力量房、球员背影；明亮，不出现具体文字','banner')}<h2>${career.stage==='preseason'?'新秀训练营':'休赛期 · 下一年从这里开始'}</h2><div class="off-points"><div><b>${career.devPoints>0?'还有成长点可用':'成长点已用完'}</b></div><div class="point-orb"><b>${career.devPoints}</b><span>POINTS</span></div></div></section>${career.stage==='preseason'?`<div class="off-body">${offTrain()}</div><button class="btn primary off-next" onclick="beginSeason()">正式进入新秀赛季 →</button>`:`<div class="off-tabs"><button class="${ui.offTab==='train'?'active':''}" onclick="ui.offTab='train';render()">能力加点</button><button class="${ui.offTab==='contract'?'active':''}" onclick="ui.offTab='contract';render()">合同续约</button><button class="${ui.offTab==='trade'?'active':''}" onclick="ui.offTab='trade';render()">交易申请</button></div><div class="off-body">${ui.offTab==='train'?offTrain():ui.offTab==='contract'?offContract():offTrade()}</div><button class="btn primary off-next" onclick="nextSeason()">完成休赛期 · 进入下一赛季 →</button>`}`}
function seasonView(){if(career.stage==='preseason'||career.stage==='offseason')return offseasonView();if(career.stage==='regular')return regularView();if(career.stage==='allstar')return allStarView();if(career.stage==='postgate')return postGateView();if(career.stage==='playin')return playInView();if(career.stage==='playoffs')return playoffView();return regularView()}
function playerView(){let p=currentP();return `<section class="profile-hero"><div class="profile-grid">${asset(`【素材位：${p.zh}球员详情立绘】`,'用途：球员详情页人物素材')}<div class="profile-copy"><small>${p.en} · ${p.pos}</small><h2>${p.zh}</h2><p>${p.desc}</p><div class="scenario-tags">${career.talents.map(id=>{let t=talents.find(x=>x.id===id);return `<span>${t?t.n:p.exclusive.n}</span>`}).join('')}</div></div></div><div class="attr-grid">${Object.entries(ATTR).map(([k,v])=>`<div class="attr"><header><span>${v}</span><b>${career.attrs[k]}</b></header><i><b style="width:${clamp(career.attrs[k])}%"></b></i></div>`).join('')}</div></section><section class="news-stage"><header><h3>当前身份</h3><small>球员状态</small></header><div class="headline"><div class="stamp">OVR</div><p><b>${career.ovr} · ${career.role}</b><br>${teamBy(career.team).name} · 合同剩余${career.contract.years}年 · 年薪${career.contract.salary}M</p></div></section>`}
function storyView(){let p=currentP(),arr=campaigns[p.id],end=mainlineEnding();return `<section class="story-banner">${asset(`【素材位：${p.zh}专属主线章节视觉】`,'用途：纪录片式主线章节封面；每名状元必须有完全不同的美术主题','banner')}<small>EXCLUSIVE CAMPAIGN</small><h2>${p.title}</h2><p>${p.desc}<br><b>专属主线不是通用事件换名字：</b>触发条件、核心数值和最终解法都跟这个人绑定。</p></section><div class="story-outcome"><div class="seal">${career.storyIndex}/6</div><div><small>当前世界线倾向</small><b>${end[0]}</b><p>${end[1]}</p></div></div><div class="chapters">${arr.map((x,i)=>`<div class="chapter ${i<career.storyIndex?'done':i===career.storyIndex?'current':''}"><div class="node">${i<career.storyIndex?'✓':i+1}</div><div><strong>${x.t}</strong><p>${i<career.storyIndex?'已经写入你的世界线。':i===career.storyIndex?'当前章节；只有达到属于这个剧本的条件才会触发。':'尚未解锁。'}</p></div></div>`).join('')}</div>`}
function leagueView(){let all=[...teams].map(t=>({t,w:projectedWins(t)})).sort((a,b)=>b.w-a.w),rank=all.slice(0,10),my=all.findIndex(x=>x.t.abbr===career.team);let rows=rank.map((x,i)=>`<div class="standing"><i>${i+1}</i><strong>${x.t.name}${x.t.abbr===career.team?' · 你的球队':''}</strong><span>${x.w}胜</span></div>`).join('');if(my>=10){let x=all[my];rows+=`<div class="standing" style="opacity:.55"><i>…</i><strong>其余球队</strong><span></span></div><div class="standing" style="background:#fff1e8"><i>${my+1}</i><strong>${x.t.name} · 你的球队</strong><span>${x.w}胜</span></div>`}return `<section class="league-stage">${asset('【素材位：联盟页面顶部主视觉】','用途：联盟球馆/东西部地图氛围背景，不出现具体球队文字','banner')}<h2>联盟风向</h2><div class="standings">${rows}</div></section><section class="news-stage"><header><h3>交易市场</h3><small>MARKET</small></header><div class="headline"><div class="stamp">GM</div><p><b>${managementStance()[0]}</b><br>${managementStance()[1]} 申请交易只改变方向与概率，不会把你直接传送到指定球队。</p></div></section>`}
function legacyView(){return `<section class="legacy-stage">${asset('【素材位：生涯荣誉陈列馆背景】','用途：奖杯墙/球衣退役馆氛围，不放具体奖杯文字','banner')}<h2>你的新世界线</h2><div class="honor-wall">${Object.entries(career.honors).map(([k,v])=>`<div class="honor">${asset(`【素材位：${k}奖杯图标】`,'透明PNG','')}<b>${k}</b><span>× ${v}</span></div>`).join('')}</div><div class="history">${career.history.slice().reverse().map(h=>`<div class="history-row"><b>${h.season}</b><div><p>${teamBy(h.team).name} · ${h.record}</p><p>${fmt(h.stats.pts)}分 ${fmt(h.stats.reb)}板 ${fmt(h.stats.ast)}助 · ${h.result}</p></div><strong>${h.ovr}</strong></div>`).join('')||'<div class="tiny">完成第一个赛季后，这里会形成完整的生涯年表。</div>'}</div><div class="retire-box"><b>主动退役</b><p>你可以在任何阶段决定结束这条世界线。系统会生成最终生涯报告和命运改写评价。</p><button onclick="ui.modal={kind:'retire'};render()">宣布退役</button></div></section>`}
function renderCareer(){return `<section class="career">${renderHud()}<main class="career-main">${ui.tab==='season'?seasonView():ui.tab==='player'?playerView():ui.tab==='story'?storyView():ui.tab==='league'?leagueView():legacyView()}</main><nav class="dock">${[['season','赛季','▶'],['player','球员','◉'],['story','主线','◆'],['league','联盟','⌁'],['legacy','生涯','★']].map(([id,n,ic])=>`<button class="${ui.tab===id?'active':''}" onclick="stopSim();ui.tab='${id}';render()"><i>${ic}</i>${n}</button>`).join('')}</nav>${ui.toast?`<div class="toast">${esc(ui.toast)}</div>`:''}${renderOverlay()}</section>`}
function renderOverlay(){if(ui.storyEvent){let e=ui.storyEvent;return `<div class="overlay"><div class="sheet"><div class="sheet-handle"></div>${asset('【素材位：该主线章节剧情插图】','用途：当前专属主线事件的剧情插画；不同章节可替换，不要文字')}<small>EXCLUSIVE STORY · ${currentP().zh}</small><h2>${e.t}</h2><p>${e.b}</p><div class="choice-list">${e.c.map((c,i)=>`<button class="choice" onclick="storyChoice(${i})"><b>${c[0]}</b><span>${c[1]}</span></button>`).join('')}</div><div class="sheet-footer"><span>选择会永久影响这条世界线</span><span>主线 ${career.storyIndex+1}/6</span></div></div></div>`}
 if(!ui.modal)return'';let m=ui.modal;if(m.kind==='injury'){let i=career.injury;return `<div class="overlay"><div class="sheet"><div class="sheet-handle"></div><div class="injury-card"><div class="alert"><div class="injury-icon">✚</div><div><small>MEDICAL REPORT</small><h2>${i.name}</h2></div></div><p>医疗组预计缺席约 ${i.baseGames} 场。你可以保守恢复、按标准方案治疗，也可以冒风险提前回来。</p><div class="choice-list"><button class="choice" onclick="chooseInjury('safe')"><b>保守休战</b><span>缺席更久，但健康恢复更多，复发风险下降。</span></button><button class="choice" onclick="chooseInjury('standard')"><b>标准治疗</b><span>按照医疗组计划恢复，不额外赌未来。</span></button><button class="choice danger" onclick="chooseInjury('rush')"><b>加速复出</b><span>明显缩短缺席时间，但健康和复发风险会恶化。</span></button></div></div></div></div>`}
 if(m.kind==='trade'||m.kind==='offtrade'){let d=m.dest;return `<div class="overlay"><div class="sheet"><div class="sheet-handle"></div>${asset('【素材位：交易新闻主视觉】','用途：交易官宣/机场/球衣交换氛围图，不放具体名字文字')}<small>BREAKING TRANSACTION</small><h2>你被交易到 ${d.name}</h2><p>${m.reason||'管理层完成了一笔休赛期交易。'} 这不是玩家自己指定跳队，而是球队和市场共同做出的结果。</p><button class="btn primary" style="width:100%" onclick="acceptTrade()">接受新的球队与人生 →</button></div></div>`}
 if(m.kind==='retire')return `<div class="overlay"><div class="sheet"><div class="sheet-handle"></div><small>CAREER DECISION</small><h2>真的要结束这段职业生涯吗？</h2><p>退役后会立即生成最终报告。这条世界线将作为你的存档结局保留。</p><div class="confirm-row"><button class="cancel" onclick="ui.modal=null;render()">继续打</button><button class="ok" onclick="ui.modal=null;retire()">宣布退役</button></div></div></div>`;return''}
function renderRetired(){let p=currentP(),score=destinyScore(),grade=score>=90?'另一条传奇':score>=75?'改写历史':score>=58?'彻底翻案':score>=42?'证明自己':score>=25?'站稳联盟':'历史如旧',me=mainlineEnding();return `<section class="retired"><div class="retired-card">${asset(`【素材位：${p.zh}退役生涯海报】`,'用途：最终世界线纪念海报；人物+球馆/荣誉氛围，不要文字','tall')}<small>生涯结束 · ${career.draftYear}—${career.seasonYear}</small><h1>${p.zh}</h1><p>${career.retireReason}<br><br><b>${career.playerId==='custom'?'生涯轨迹：':'原始现实轨迹：'}</b>${p.reality}</p><div class="legacy-score"><div><b>${grade}</b><div class="tiny">命运改写评价</div></div><strong>${score}%</strong></div><div class="final-grid"><div><b>${career.careerTotals.seasons}</b><span>赛季</span></div><div><b>${career.honors['全明星']}</b><span>全明星</span></div><div><b>${career.honors['总冠军']}</b><span>冠军</span></div><div><b>${Math.round(career.careerTotals.points).toLocaleString()}</b><span>总得分</span></div><div><b>${career.honors['MVP']}</b><span>MVP</span></div><div><b>${career.ovr}</b><span>退役OVR</span></div></div><button class="btn primary" onclick="localStorage.removeItem('${SAVE}');career=null;ui.screen='home';render()">${career.playerId==='custom'?'重新开始新生涯':'换一个状元重新开始'}</button><button class="btn secondary" onclick="ui.screen='home';render()">返回封面</button></div></section>`}
function continueSave(){career=load();if(!career)return startSelect();ui.screen=career.retired?'retired':'career';ui.tab='season';render()}
// Route names only select trusted renderers; route values are never HTML content.
function render(){
 const app=$('#app');
 let html;
 switch(ui.screen){
  case 'home': html=renderHome(); break;
  case 'select': html=renderSelect(); break;
  case 'talents': html=renderTalents(); break;
  case 'draft': html=renderDraft(); break;
  case 'career': html=renderCareer(); break;
  case 'retired': html=renderRetired(); break;
  default: ui.screen='home'; html=renderHome(); break;
 }
 app.innerHTML=html;
}

