function ensureWorldline(){
 if(!career)return;
 if(!career.worldline)career.worldline={diverged:false,divergence:null,nodes:[],events:[],choices:[],longArcSeasons:[]};
 const w=career.worldline;
 if(!Array.isArray(w.nodes))w.nodes=[];if(!Array.isArray(w.events))w.events=[];if(!Array.isArray(w.choices))w.choices=[];if(!Array.isArray(w.longArcSeasons))w.longArcSeasons=[];
 if(career.history?.length){career.history.forEach((h,idx)=>{let sn=idx+1;if(!w.nodes.some(n=>n.seasonNo===sn))w.nodes.push({seasonNo:sn,label:h.season,title:`${teamBy(h.team).name} · ${h.result}`,detail:`${fmt(h.stats.pts)}分 ${fmt(h.stats.reb)}板 ${fmt(h.stats.ast)}助 · OVR ${h.ovr}`})})}
}
function addWorldEvent(title,detail,kind='event'){ensureWorldline();let w=career.worldline;if(w.events.some(e=>e.seasonNo===career.seasonNo&&e.title===title))return;w.events.push({seasonNo:career.seasonNo,label:seasonLabel(),title,detail,kind});w.events=w.events.slice(-40)}
function markDivergence(title,reason,nativeText,yoursText){ensureWorldline();let w=career.worldline;if(w.diverged)return false;w.diverged=true;w.divergence={seasonNo:career.seasonNo,label:seasonLabel(),game:career.games,title,reason,native:nativeText,yours:yoursText};career.feed.unshift(`世界线发生分歧：${title}`);stopSim();ui.modal={kind:'divergence',data:w.divergence};save();render();return true}
function evaluateWorldline(){
 if(!career)return false;ensureWorldline();if(career.worldline.diverged)return false;let p=career.playerId,s=career.seasonStats;
 if(p==='oden'&&career.seasonNo===1&&s.gp>=1)return markDivergence('你在新秀赛季真正登场了','现实中的奥登整个2007-08赛季没有出场。','现实：膝部手术，赛季报销。',`你的世界：第${career.games}场前已经完成NBA出场。`);
 if(p==='simmons'&&career.seasonNo===1&&s.gp>=1)return markDivergence('第一场NBA比赛就改写了历史','现实中的西蒙斯整个2016-17赛季因脚伤缺席。','现实：新秀赛季0场。',`你的世界：第${career.games}场已经登场。`);
 if(p==='bennett'&&career.seasonNo===1&&career.games>=20&&(s.pts>=8||career.trust>=56||career.ovr>=77))return markDivergence('你提前摆脱了新秀期失控','你的前20场表现已经明显越过现实线的低迷轨迹。','现实：角色、效率和信心持续恶化。',`你的世界：${fmt(s.pts)}分 · OVR ${career.ovr} · 信任${career.trust}。`);
 if(p==='bennett'&&career.seasonNo>=2&&career.team!=='MIN')return markDivergence('第一笔关键交易没有按现实发生','现实线第二年已经离开克利夫兰前往明尼苏达。','现实：第二季进入森林狼。',`你的世界：第二季效力${teamBy(career.team).name}。`);
 if(p==='kwame'&&career.seasonNo===1&&career.games>=30&&(s.pts>=8||career.ovr>=79||career.trust>=62))return markDivergence('十九岁的你提前站稳了脚跟','现实线的新秀年长期处于有限角色。','现实：首季只是有限轮换。',`你的世界：${fmt(s.pts)}分 · ${career.role} · OVR ${career.ovr}。`);
 if(p==='kwame'&&career.seasonNo>=5&&career.team!=='LAL')return markDivergence('奇才之后的去向改变了','现实线第五季前往洛杉矶。','现实：生涯第二阶段进入湖人。',`你的世界：第五季来到${teamBy(career.team).name}。`);
 if(p==='fultz'&&career.seasonNo===1&&career.games>=20&&(s.gp>=18||career.special>=50||s.pts>=10))return markDivergence('投篮问题没有像现实那样吞掉新秀年','你的出勤或投篮稳定已经明显越过现实同期。','现实：新秀赛季长期受肩部与投篮问题影响。',`你的世界：已出战${s.gp}场，投篮稳定${career.special}。`);
 if(p==='fultz'&&career.seasonNo>=3&&career.team!=='ORL')return markDivergence('费城之后，你去了另一条路','现实线第二季结束前后已经进入奥兰多阶段。','现实：前往魔术重新开始。',`你的世界：第三季效力${teamBy(career.team).name}。`);
 if(career.honors['MVP']>0||career.honors['总冠军']>0)return markDivergence('历史从荣誉簿上彻底分叉','现实线从未出现这一项同阶段成就。','现实：没有这项同阶段荣誉。',`你的世界：已经写下${career.honors['MVP']?'MVP':''}${career.honors['总冠军']?' 总冠军':''}。`);
 return false;
}
function recordWorldSeason(result){ensureWorldline();let h=career.history?.[career.history.length-1];if(!h)return;let w=career.worldline,n=w.nodes.find(x=>x.seasonNo===career.seasonNo);let data={seasonNo:career.seasonNo,label:h.season,title:`${teamBy(h.team).name} · ${h.result}`,detail:`${fmt(h.stats.pts)}分 ${fmt(h.stats.reb)}板 ${fmt(h.stats.ast)}助 · ${h.record} · OVR ${h.ovr}`};if(n)Object.assign(n,data);else w.nodes.push(data)}
function currentWorldNode(sn){ensureWorldline();let n=career.worldline.nodes.find(x=>x.seasonNo===sn);if(n)return n;if(sn===career.seasonNo){let s=career.seasonStats;return {seasonNo:sn,label:seasonLabel(),title:`${teamBy(career.team).name} · ${seasonPhase()}`,detail:`${career.role} · ${fmt(s.pts)}分 ${fmt(s.reb)}板 ${fmt(s.ast)}助 · OVR ${career.ovr}`}}return null}
function nextNativeHint(){let arr=historyBlueprints[career.playerId]||[],n=arr.find(x=>x.season>=career.seasonNo);return n?`${n.label} · ${n.title}`:'现实NBA生涯的主要节点已经走完'}
function makeLongArcEvent(){
 let p=currentP(),age=career.age,sn=career.seasonNo,late=age>=31,prime=career.ovr>=88;
 const cfg={
  bennett:{young:['标签已经追不上你','当你终于不需要再解释“为什么是状元”，真正的问题变成：你想成为哪一种球员？'],prime:['从逆袭故事变成球队责任','媒体不再把你当笑话，而是开始要求你赢球。旧标签消失以后，责任反而更重。'],late:['最后一次听见那个旧称呼','职业生涯进入后段，“最差状元”又被写进回顾文章。现在它已经只是很远的过去。']},
  oden:{young:['健康不再是一天，而是一整年','连续出场开始让“如果健康”变成“他真的在打”。越接近巅峰，负荷诱惑越大。'],prime:['巅峰身体的使用权','你已经有资格决定一支球队的季后赛上限，但每一次拉满分钟都在和未来做交换。'],late:['老化让风险重新回来','年轻时的伤病史不会消失。现在需要决定，是继续冲击，还是让生涯活得更长。']},
  kwame:{young:['你不再需要像一个状元','当技术和心态终于成熟，最重要的变化是：你开始按照自己的方式打球。'],prime:['从被培养的人变成可靠的人','球队开始依赖你的防守、对抗和经验。你可以继续追上限，也可以成为最稳定的内线。'],late:['你开始教年轻人如何活下来','曾经被聚光灯压得喘不过气的年轻状元，现在成了更衣室里最懂压力的人。']},
  fultz:{young:['投篮问题不再是全部身份','当动作重新稳定，真正的选择才开始：你到底要成为得分手、组织者，还是攻防一体的后卫？'],prime:['正常打球，反而成了最大的胜利','曾经每次出手都被研究。现在没人讨论动作了，只讨论你能不能带队赢。'],late:['身体和投篮都需要新的版本','速度不再像年轻时那样轻松，你必须用节奏、组织和经验延长自己的价值。']},
  simmons:{young:['天赋之外，必须主动选择打法','你可以继续做最强的非投射核心，也可以彻底改变自己对进攻的态度。'],prime:['季后赛会再次问同一个问题','常规赛的全能无法隐藏关键回合。你必须决定是否愿意主动承担进攻失败的风险。'],late:['运动能力下降以后，你还剩什么','当转换速度和爆发不再占绝对优势，组织、防守和技术必须重新排列。']}
 }[p.id];
 let x=late?cfg.late:prime?cfg.prime:cfg.young;
 let choices={
  bennett:[['成为稳定的两端首发','防守+2，耐久+2，信任+4',{a:{defense:2,durability:2},tr:4}],['继续追求得分上限','投射+2，终结+2，健康-2',{a:{shooting:2,finishing:2},h:-2}],['把职业长度放第一','耐久+3，健康+6',{a:{durability:3},h:6}]],
  oden:[['严格控制负荷','健康+7，身体风险-7',{h:7,s:-7}],['为季后赛保留火力','防守+2，耐久+2',{a:{defense:2,durability:2},s:-2}],['继续冲击统治力','终结+3，篮板+2，风险+7',{a:{finishing:3,rebounding:2},s:7}]],
  kwame:[['做顶级防守内线','防守+3，篮板+2',{a:{defense:3,rebounding:2}}],['继续开发进攻','终结+2，投射+2',{a:{finishing:2,shooting:2}}],['成为更衣室领袖','心态+3，信任+6',{a:{mentality:3},tr:6}]],
  fultz:[['持球组织核心','组织+3，心态+2',{a:{playmaking:3,mentality:2}}],['继续把投篮练成武器','投射+3，稳定+4',{a:{shooting:3},s:4}],['攻防平衡','防守+2，耐久+2',{a:{defense:2,durability:2}}]],
  simmons:[['彻底接受组织前锋路线','组织+2，防守+2，信任+4',{a:{playmaking:2,defense:2},tr:4}],['继续逼自己投','投射+3，出手欲望+4',{a:{shooting:3},s:4}],['转型内线发动机','终结+2，篮板+3',{a:{finishing:2,rebounding:3}}]]
 }[p.id];
 return {_longArc:true,t:`${seasonLabel()} · ${x[0]}`,b:x[1],c:choices};
}
const __oldMaybeStory=maybeStory;
maybeStory=function(){
 ensureWorldline();
 if(career.storyIndex<6)return __oldMaybeStory();
 if(career.stage==='regular'&&career.games>=8&&!career.worldline.longArcSeasons.includes(career.seasonNo)){
  stopSim();ui.storyEvent=makeLongArcEvent();save();render();return true;
 }
 return false;
};
const __oldStoryChoice=storyChoice;
storyChoice=function(i){
 let ev=ui.storyEvent;if(!ev)return;
 if(ev._longArc){let ch=ev.c[i];applyFx(ch[2]);ensureWorldline();career.worldline.longArcSeasons.push(career.seasonNo);career.worldline.choices.push({seasonNo:career.seasonNo,label:seasonLabel(),title:ev.t,choice:ch[0],detail:ch[1]});career.feed.unshift(`生涯主线「${ev.t}」：你选择了“${ch[0]}”。`);ui.storyEvent=null;save();render();return}
 let title=ev.t,choice=ev.c[i][0],detail=ev.c[i][1];__oldStoryChoice(i);ensureWorldline();career.worldline.choices.push({seasonNo:career.seasonNo,label:seasonLabel(),title,choice,detail});save();
};
const __oldCreateCareer=createCareer;
createCareer=function(){__oldCreateCareer();ensureWorldline();save()};
const __oldSimulateGame=simulateGame;
simulateGame=function(){__oldSimulateGame();if(career&&!career.retired){ensureWorldline();evaluateWorldline();save()}};
const __oldEndSeason=endSeason;
endSeason=function(result){__oldEndSeason(result);if(career&&!career.retired){ensureWorldline();recordWorldSeason(result);evaluateWorldline();save();render()}};
const __oldNextSeason=nextSeason;
nextSeason=function(){let before=career?.seasonNo;__oldNextSeason();if(career&&!career.retired&&career.seasonNo!==before){ensureWorldline();evaluateWorldline();save();render()}};
const __oldAcceptTrade=acceptTrade;
acceptTrade=function(){let old=career?.team,d=ui.modal?.dest;__oldAcceptTrade();if(career&&old!==career.team){addWorldEvent('生涯发生交易',`${teamBy(old).name} → ${teamBy(career.team).name}`,'trade');evaluateWorldline();save();render()}};
const __oldAcceptOffer=acceptOffer;
acceptOffer=function(i){let old=career?.team;__oldAcceptOffer(i);if(career&&old!==career.team)addWorldEvent('自由市场改变球队',`${teamBy(old).name} → ${teamBy(career.team).name}`,'contract');save()};
const __oldMaybeAllStar=maybeAllStar;
maybeAllStar=function(){let r=__oldMaybeAllStar();if(r&&career.allStar)addWorldEvent('入选全明星',`${seasonLabel()}，生涯身份出现跃迁。`,'honor');evaluateWorldline();save();return r};
const __oldTriggerInjury=triggerInjury;
triggerInjury=function(){__oldTriggerInjury();if(career?.injury&&career.injury.severity==='major')addWorldEvent('重大伤病',`${career.injury.name} · 预计缺席${career.injury.baseGames}场`,'injury');save()};
function renderHome(){let s=load();return `<section class="case-cover"><div class="case-topbar"><div><b>CASE FILE / NO.1 PICK</b><br>CAREER RECONSTRUCTION PROGRAM</div><span>V2.2 · WORLDLINE</span></div><div class="case-visual">${asset('【素材位：封面纪录片主视觉】','用途：五位状元以纪录片拼贴/选秀档案形式出现；画面明亮、高级、有纸张与球馆光影感；不要做成五张人物卡，不要任何文字。','tall')}<div class="case-number"><b>01</b><span>REWRITE<br>THE CAREER</span></div><div class="case-stamp">NO.1<br>PICK</div></div><div class="case-paper"><div class="case-eyebrow"><span>FIVE CAREERS · ONE SECOND CHANCE</span><b>命运可改写</b></div><h1 class="case-title"><span>拯救</span><em>水货状元</em></h1><p class="case-desc">从选秀夜开始，不是观看历史，而是亲手把一条真实生涯拽向另一条世界线。第一次和原历史不同的那一刻，会成为你永久的“分歧点”。</p><div class="case-route"><div><b>选秀夜</b><span>DRAFT</span></div><div><b>82场</b><span>SEASON</span></div><div><b>分歧树</b><span>BRANCH</span></div><div><b>到退役</b><span>LEGACY</span></div></div><div class="case-people"><span>本内特 · 翻案</span><span>奥登 · 健康</span><span>夸梅 · 成长</span><span>富尔茨 · 投篮</span><span>西蒙斯 · 重塑</span></div><div class="case-actions"><button class="btn primary" onclick="startSelect()">打开第一份生涯档案 →</button>${s?`<button class="btn secondary" onclick="continueSave()">继续 ${esc((playerBy(s.playerId)||{}).zh||'未知球员')} · ${s.seasonYear}-${String((s.seasonYear+1)%100).padStart(2,'0')}</button>`:''}</div></div></section>`}
function renderHud(){let p=currentP();return `<header class="career-hud"><div><small>${seasonLabel()} · ${career.age}岁 · ${seasonPhase()}</small><h2>${p.zh}<span> / ${teamBy(career.team).name}</span></h2></div><div class="hud-right">${asset('【球队Logo素材位】',career.team,'logo')}<div class="ovr-orb"><span>OVR</span><b>${career.ovr}</b></div></div></header>`}
function seasonHero(){let p=currentP(),prog=career.stage==='regular'?career.games/82*100:career.stage==='allstar'?50:100;return `<section class="season-brief"><div class="season-brief-art">${asset(`【素材位：${p.zh}赛季主视觉】`,'用途：当前球队时期的球员横幅主视觉；人物与球馆环境，不含任何文字。')}<div class="season-brief-copy"><small>${seasonLabel()} · YEAR ${career.seasonNo}</small><h2>${career.role}</h2><p>${career.feed[0]||p.tagline}</p></div><div class="season-brief-score"><b>${career.games}/82</b><span>${teamRecord()}</span></div></div><div class="season-brief-bottom"><div><b>${seasonPhase()}</b><span>当前阶段</span></div><div><b>${career.health}</b><span>健康</span></div><div><b>${career.confidence}</b><span>自信</span></div><div><b>${career.special}</b><span>${p.specialName}</span></div></div></section>`}
function compactRecentGames(){let g=career.gameLog.slice(0,3);return `<div class="compact-games">${g.map(x=>`<div class="compact-game ${x.win?'win':'loss'}"><span class="wl">${x.win?'W':'L'}</span><div><b>${career.team} ${x.sf}:${x.sa} ${x.opp}</b><span>${x.played===false?'伤病缺阵':`${fmt(x.line?.pts)}分 · ${fmt(x.line?.reb)}板 · ${fmt(x.line?.ast)}助`}</span></div><small>G${x.n}</small></div>`).join('')||'<div class="tiny">还没有比赛记录。</div>'}</div>`}
function nextBeatData(){if(career.games<41)return['全明星名单',`距离全明星节点还有${41-career.games}场。`];if(career.games<55)return['交易截止日',`还有${55-career.games}场进入交易截止节点。`];if(career.games<82)return['常规赛收官',`还剩${82-career.games}场，排名与季后赛席位仍会变化。`];return['季后赛入口','常规赛已经完成，等待结算。']}
function regularView(){let s=career.seasonStats,p=currentP(),nb=nextBeatData(),m=seasonMission();return `${seasonHero()}<section class="focus-sim"><header><div><small>LIVE REGULAR SEASON</small><b>常规赛连续模拟</b></div><span class="tiny">随时暂停</span></header><div class="focus-actions"><button class="run ${ui.sim?'running':''}" onclick="toggleSim()">${ui.sim?'Ⅱ 暂停模拟':'▶ 继续这段生涯'}</button><button class="speed" onclick="changeSpeed()">${ui.speed===450?'1×':ui.speed===220?'2×':'4×'}</button></div><div class="beans-head"><b>最近20场</b><span>绿=胜 · 红=负 · 灰点=伤停</span></div>${renderBeans()}<div class="season-trackline"><i style="width:${clamp(career.games/82*100)}%"></i></div><div class="season-trackmeta"><span>G1</span><b>${career.games}/82 · ${teamRecord()}</b><span>G82</span></div></section><div class="focus-stats"><div><b>${fmt(s.pts)}</b><span>场均得分</span></div><div><b>${fmt(s.reb)}</b><span>场均篮板</span></div><div><b>${fmt(s.ast)}</b><span>场均助攻</span></div></div>${career.injury?`<div class="injury-mini"><b>${career.injury.name}</b> · 预计还缺席${career.injury.gamesLeft}场。球队比赛照常推进。</div>`:''}<div class="next-beat"><i>◆</i><div><small>NEXT BIG MOMENT</small><b>${nb[0]}</b><p>${nb[1]} · 本季主线：${m.t}</p></div></div>${compactRecentGames()}`}
function worldlineRows(){ensureWorldline();let hist=historyBlueprints[career.playerId]||[],w=career.worldline,div=w.divergence,maxNative=Math.max(...hist.map(x=>x.season),1),max=Math.max(career.seasonNo,maxNative);let rows='';for(let sn=1;sn<=max;sn++){let h=hist.find(x=>x.season===sn),mine=currentWorldNode(sn),fork=div&&div.seasonNo===sn,after=div&&sn>=div.seasonNo;let events=w.events.filter(e=>e.seasonNo===sn).slice(-2);if(mine&&events.length)mine={...mine,detail:mine.detail+' · '+events.map(e=>e.title).join(' / ')};rows+=`<div class="tree-row ${fork?'fork':''} ${after?'after':''}"><div class="tree-side">${h?`<div class="tree-node native"><small>${h.label}</small><b>${h.title}</b><p>${h.detail}</p></div>`:`<div class="tree-node empty"></div>`}</div><div class="tree-spine"><span class="tree-dot"></span></div><div class="tree-side">${mine?`<div class="tree-node mine"><small>${mine.label}</small><b>${mine.title}</b><p>${mine.detail}</p></div>`:(after&&sn<=career.seasonNo?`<div class="tree-node mine"><small>你的世界</small><b>这一季仍在书写</b><p>比赛、交易、伤病与选择都会继续进入这条线。</p></div>`:`<div class="tree-node empty"></div>`)}</div><div class="tree-season">YEAR ${sn}${fork?' · 首个分歧点':''}</div></div>`}return rows}
function storyView(){ensureWorldline();let p=currentP(),w=career.worldline,end=mainlineEnding(),div=w.divergence;return `<section class="worldline-head"><small>ORIGINAL HISTORY × YOUR WORLDLINE</small><h2>${p.zh} · 生涯分歧树</h2><p>灰色是原生涯的关键节点，红色是你模拟出来的世界。主线不会在第6章结束：核心剧本结束后，每个新赛季仍会生成一章只属于${p.zh}的生涯主线。</p>${div?`<div class="divergence-card"><div class="fork">Y</div><div><small>FIRST DIVERGENCE · ${div.label}${div.game?` · G${div.game}`:''}</small><b>${div.title}</b><p>${div.reason}</p></div></div>`:`<div class="divergence-card"><div class="fork" style="background:#9b9087">＝</div><div><small>仍与原历史线重合</small><b>下一个现实节点：${nextNativeHint()}</b><p>当出勤、表现、球队去向或关键选择第一次明显不同，这里会自动记录首个分歧点。</p></div></div>`}</section><div class="line-legend"><span class="native">原生涯</span><span>↯</span><span class="mine">你的世界线</span></div><div class="timeline-tree">${worldlineRows()}</div><div class="branch-choices"><h3>已经写入世界线的关键选择</h3>${w.choices.slice().reverse().slice(0,8).map((c,i)=>`<div class="branch-choice"><i>${w.choices.length-i}</i><div><b>${c.label} · ${c.choice}</b><p>${c.title}</p></div></div>`).join('')||'<div class="tiny">主线选择发生后会记录在这里。</div>'}</div><div class="story-outcome"><div class="seal">◆</div><div><small>当前世界线倾向</small><b>${end[0]}</b><p>${end[1]}</p></div></div>`}
function renderCareer(){ensureWorldline();return `<section class="career">${renderHud()}<main class="career-main">${ui.tab==='season'?seasonView():ui.tab==='player'?playerView():ui.tab==='story'?storyView():ui.tab==='league'?leagueView():legacyView()}</main><nav class="dock">${[['season','赛季','▶'],['player','球员','◉'],['story','世界线','⑂'],['league','联盟','⌁'],['legacy','生涯','★']].map(([id,n,ic])=>`<button class="${ui.tab===id?'active':''}" onclick="stopSim();ui.tab='${id}';render()"><i>${ic}</i>${n}</button>`).join('')}</nav>${ui.toast?`<div class="toast">${esc(ui.toast)}</div>`:''}${renderOverlay()}</section>`}
const __oldRenderOverlay=renderOverlay;
renderOverlay=function(){if(ui.modal?.kind==='divergence'){let d=ui.modal.data;return `<div class="overlay"><div class="sheet"><div class="sheet-handle"></div><div class="fork-modal"><div class="fork-symbol">Y</div><small>HISTORY DIVERGED · ${d.label}</small><h2>从这里开始，不再是原来的生涯</h2><p>${d.reason}</p><div class="fork-compare"><div class="old"><b>原生涯</b><p>${d.native}</p></div><div class="new"><b>你的世界线</b><p>${d.yours}</p></div></div><button class="btn primary" style="width:100%" onclick="ui.modal=null;save();render()">知道了 · 继续生涯</button></div></div></div>`}return __oldRenderOverlay()};
const __oldContinueSave=continueSave;
continueSave=function(){__oldContinueSave();ensureWorldline();save()};
window.addEventListener('beforeunload',stopSim);render();
